static void inorder(struct TreeNode *node, struct TreeNode **prev) {
  if (!node) return;
  inorder(node->left, prev);
  node->left = NULL;
  (*prev)->right = node;
  *prev = node;
  inorder(node->right, prev);
}

struct TreeNode *convertBiNode(struct TreeNode *root) {
  struct TreeNode dummy = {0, NULL, NULL};
  struct TreeNode *prev = &dummy;
  inorder(root, &prev);
  if (prev) prev->right = NULL;
  return dummy.right;
}

class Solution {
  void inorder(TreeNode *node, TreeNode *&prev) {
    if (!node) return;
    inorder(node->left, prev);
    node->left = nullptr;
    prev->right = node;
    prev = node;
    inorder(node->right, prev);
  }

public:
  TreeNode *convertBiNode(TreeNode *root) {
    TreeNode dummy(0);
    TreeNode *prev = &dummy;
    inorder(root, prev);
    prev->right = nullptr;
    return dummy.right;
  }
};

func convertBiNode(root *TreeNode) *TreeNode {
	dummy := &TreeNode{}
	prev := dummy
	var inorder func(node *TreeNode)
	inorder = func(node *TreeNode) {
		if node == nil {
			return
		}
		inorder(node.Left)
		node.Left = nil
		prev.Right = node
		prev = node
		inorder(node.Right)
	}
	inorder(root)
	prev.Right = nil
	return dummy.Right
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private TreeNode prev = new TreeNode(0);

  private void inorder(TreeNode node) {
    if (node == null) return;
    inorder(node.left);
    node.left = null;
    prev.right = node;
    prev = node;
    inorder(node.right);
  }

  public TreeNode convertBiNode(TreeNode root) {
    TreeNode dummy = new TreeNode(0);
    prev = dummy;
    inorder(root);
    prev.right = null;
    return dummy.right;
  }
}

impl Solution {
  pub fn convert_bi_node(root: Option<Box<TreeNode>>) -> Option<Box<TreeNode>> {
    let mut vals = vec![];
    fn inorder(node: &Option<Box<TreeNode>>, vals: &mut Vec<i32>) {
      if let Some(n) = node {
        inorder(&n.left, vals);
        vals.push(n.val);
        inorder(&n.right, vals);
      }
    }
    inorder(&root, &mut vals);
    let mut dummy = TreeNode::new(0);
    let mut tail = &mut dummy;
    for v in vals {
      tail.right = Some(Box::new(TreeNode::new(v)));
      tail = tail.right.as_mut().unwrap();
    }
    dummy.right
  }
}

const convertBiNode = (root: TreeNode | null): TreeNode | null => {
  const dummy = new TreeNode(0);
  let prev: TreeNode = dummy;
  const inorder = (node: TreeNode | null) => {
    if (!node) return;
    inorder(node.left);
    node.left = null;
    prev.right = node;
    prev = node;
    inorder(node.right);
  };
  inorder(root);
  prev.right = null;
  return dummy.right;
};
